JSValue run(const JSValue&request){auto s=JSValue::object();s.set("vars",JSValue::object());s.set("events",array());s.set("outputs",array());const auto steps=request.get("steps");for(unsigned i=0;i<steps.length();++i)step(steps.get(JSValue(i)),s);auto out=JSValue::object();out.set("outputs",s.get("outputs"));out.set("events",s.get("events"));return out;}
JSValue metadata(){auto out=JSValue::object();for(const auto*name:{"DataMap","ChainMap","NodeBuilderState","RenderObject","RenderObjects"}){const auto ctor=constructor(name),proto=ctor.get("prototype");auto row=JSValue::object(),methods=array(),keys=array();row.set("name",ctor.get("name"));row.set("length",ctor.get("length"));row.set("source",ctor.nativeFunctionSource());for(const auto&key:proto.ownPropertyKeys()){append(keys,key);if(key.strictEquals("constructor"))continue;const auto d=proto.getOwnPropertyDescriptor(key);for(const auto*kind:{"value","get","set"}){const auto fn=std::string_view(kind)=="value"?d->value:std::string_view(kind)=="get"?d->getter:d->setter;if(!fn||!fn->isCallable())continue;auto method=JSValue::object();method.set("key",key);method.set("kind",kind);method.set("name",fn->get("name"));method.set("length",fn->get("length"));method.set("source",fn->nativeFunctionSource());method.set("writable",d->writable?JSValue(*d->writable):JSValue(nullptr));method.set("enumerable",d->enumerable.value_or(false));method.set("configurable",d->configurable.value_or(false));method.set("constructible",fn->isConstructible());append(methods,method);}}row.set("prototypeKeys",keys);row.set("methods",methods);out.set(name,row);}return out;}
JSValue liveRenderObject(){auto object=EventDispatcher::runtimeConstructor().construct(),material=EventDispatcher::runtimeConstructor().construct(),geometry=EventDispatcher::runtimeConstructor().construct();geometry.set("id",0);geometry.set("attributes",JSValue::object());geometry.set("morphAttributes",JSValue::object());object.set("geometry",geometry);object.set("receiveShadow",false);material.set("version",0);auto renderer=JSValue::object(),contextNode=JSValue::object(),backend=JSValue::object();contextNode.set("id",0);contextNode.set("version",0);backend.set("isWebGPUBackend",false);renderer.set("contextNode",contextNode);renderer.set("backend",backend);renderer.set("_currentSourceMaterial",nullptr);auto nodes=JSValue::object();nodes.set("getCacheKey",JSValue::function(+[](const JSValue&,const Args&,const Args&)->JSValue{return 0;}));nodes.set("getCustomProgramCacheKey",JSValue::function(+[](const JSValue&,const Args&,const Args&)->JSValue{return "program:";}));auto geometries=JSValue::object();for(const auto*name:{"deleteNodeAttributes","deleteVertexState"})geometries.set(name,JSValue::function(+[](const JSValue&,const Args&,const Args&)->JSValue{return {};}));auto context=JSValue::object();context.set("id",0);auto ro=constructor("RenderObject").construct({nodes,geometries,renderer,object,material,JSValue::object(),JSValue::object(),JSValue::object(),context,nullptr});ro.set("onDispose",JSValue::function(+[](const JSValue&,const Args&,const Args&)->JSValue{return {};}));return ro;}
void lifetime(){for(unsigned round=0;round<3;++round){auto keep=constructor("DataMap");JSWeakValue weakKey,weakValue;{auto map=keep.construct();{auto key=JSValue::object();weakKey=JSWeakValue(key);auto value=call(map,"get",{key});value.set("cycle",key);weakValue=JSWeakValue(value);map.collectGarbage();if(weakKey.expired()||weakValue.expired())throw std::logic_error("Live DataMap ephemeron lost");}map.collectGarbage();if(!weakKey.expired()||!weakValue.expired())throw std::logic_error("Dead DataMap key/value cycle retained");}auto chain=constructor("ChainMap").construct();JSWeakValue chainKey,chainValue;{auto key=JSValue::object(),value=JSValue::object();value.set("key",key);chainKey=JSWeakValue(key);chainValue=JSWeakValue(value);call(chain,"set",{array({key}),value});chain.collectGarbage();if(chainKey.expired()||chainValue.expired())throw std::logic_error("Live chain value lost");}chain.collectGarbage();if(!chainKey.expired()||!chainValue.expired())throw std::logic_error("Dead chained ephemeron retained");auto state=constructor("NodeBuilderState").construct({"v","f",nullptr,array(),array(),array(),array(),array(),JSValue::object(),false});JSWeakValue observer(state.get("observer"));state.collectGarbage();if(observer.expired())throw std::logic_error("State observer lost");state={};keep.collectGarbage();if(!observer.expired())throw std::logic_error("Dropped State observer retained");JSWeakValue renderWeak,geometryWeak,materialWeak;{JSValue held;{auto renderObject=liveRenderObject();renderWeak=JSWeakValue(renderObject);geometryWeak=JSWeakValue(renderObject.get("geometry"));materialWeak=JSWeakValue(renderObject.get("material"));held=renderObject.get("onGeometryDispose");}keep.collectGarbage();if(renderWeak.expired()||geometryWeak.expired()||materialWeak.expired())throw std::logic_error("Held actual render callback lost owners");held.call(JSValue::object());}keep.collectGarbage();if(!renderWeak.expired()||!geometryWeak.expired()||!materialWeak.expired())throw std::logic_error("Dropped actual render callback cycle retained");}std::cout<<"3 passed\n";}
