int main(int argc,char**argv){try{auto roots=array();for(const auto*name:{"DataMap","ChainMap","NodeBuilderState","RenderObject","RenderObjects","BindGroup","EventDispatcher"})append(roots,constructor(name));if(argc==2&&std::string_view(argv[1])=="--metadata"){std::cout<<metadata().toJSON()->dump();return 0;}if(argc==2&&std::string_view(argv[1])=="--lifetime"){lifetime();return 0;}if(argc!=1)throw std::logic_error("Usage: probe [--metadata | --lifetime]");const std::string text((std::istreambuf_iterator<char>(std::cin)),{});const auto requests=Animation_detail::parseJSON(text);std::cout<<'[';for(unsigned i=0;i<requests.length();++i){if(i)std::cout<<',';{const auto result=run(requests.get(JSValue(i)));std::cout<<result.toJSON()->dump();}requests.collectGarbage();}std::cout<<']';}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
